const KEY = 'cartridge-academy-v1';
const defaults = () => ({version:2,completed:[],drafts:{},reviews:{},activities:{},journal:'',path:'~/Unamed-Project',minutes:25,artTool:'LibreSprite',lastLesson:'boot-build'});
const lessonById = id => lessons.find(l=>l.id===id);
const trackOf = l => tracks.find(t=>t.id===l.track);
function migrate(saved){
 if(saved?.version===2) return {...defaults(),...saved};
 if(saved?.version===1){const done=[...new Set((saved.completed||[]).map(n=>legacyMissionMap[n]).filter(Boolean))];return {...defaults(),completed:done,activities:saved.activities||{},journal:saved.journal||'',path:saved.path||defaults().path,minutes:[15,25,45].includes(saved.minutes)?saved.minutes:25,artTool:saved.artTool||'LibreSprite',lastLesson:done.length?(lessons.find(l=>!done.includes(l.id))?.id||defaults().lastLesson):defaults().lastLesson};}
 return null;
}
let state = defaults();
try { const m = migrate(JSON.parse(localStorage.getItem(KEY))); if (m) state = m; } catch {}
let routeCleanup = null, reviewQueue = [], reviewed = 0, reviewAttempt = '', reviewRevealed = false, reviewStarted = false;
let resourceTab = 'docs', resourceQuery = '', modalLastFocus = null;
let timerSeconds = state.minutes * 60, timerRunning = false, timerEnd = 0;
