const nextLesson = () => {const cur=lessonById(state.lastLesson),d=state.drafts[state.lastLesson];return (cur&&d&&d.step>0&&!complete(cur.id)?cur:null)||lessons.find(l=>!complete(l.id))||lessons.at(-1);};
const cards = lessons.flatMap(l=>l.check.map((c,i)=>({id:`${l.id}:${i}`,topic:l.tags[0],lesson:l.id,question:c.q,answer:`${c.options.find(o=>o.ok).t}. ${c.options.find(o=>o.ok).why}`,url:resources.find(r=>r.id===l.deeper?.[0])?.url})));
